{"intent":"Randomized consistency test of all read paths","command":"cd work/repo && python3 - <<'PY'
import sys, random, itertools
sys.path.insert(0, '.')
from boltons.cacheutils import LRU, LRI

def ll_view(c):
    "values as seen via linked list / link lookup"
    return {k: c._link_lookup[k][3] for k in c._link_lookup}  # VALUE index

def check(c, model, tag):
    # dict view
    d = dict(c)
    # link view
    lv = ll_view(c)
    if d != lv:
        print("DIVERGE", tag, "dict:", d, "ll:", lv); return False
    if d != model:
        print("MODEL-MISMATCH", tag, "cache:", d, "model:", model); return False
    # every read path
    for k in model:
        if c[k] != model[k]: print("GETITEM", tag, k); return False
        if c.get(k) != model[k]: print("GET", tag, k); return False
    if dict(c) != model or list(c.values()) != list(model.values()) \
       or list(c.items()) != list(model.items()) or list(c) != list(model) \
       or repr(c) is None:
        print("READS", tag, dict(c), model); return False
    if len(c) != len(model): print("LEN", tag); return False
    # flattened ll has same key set (incl. anchor sentinel at index)
    flat = c._get_flattened_ll()
    keys = [k for k,_ in flat[1:]]  # first is anchor
    if sorted(keys) != sorted(model): print("LLKEYS", tag, keys, model); return False
    if len(set(keys)) != len(keys): print("LLDUP", tag, keys); return False
    return True

random.seed(42)
for cls in (LRU, LRI):
    for max_size in (1, 2, 3, 5):
        for trial in range(200):
            c = cls(max_size=max_size)
            model = {}
            ops = ['set']*10 + ['del']*3 + ['pop']*2 + ['popitem']*1 + ['clear']*1
            for i in range(60):
                op = random.choice(ops)
                k = random.choice('abcdef')
                if op == 'set':
                    v = random.randint(0, 99)
                    c[k] = v
                    if k not in model and len(model) >= max_size:
                        # eviction: model must drop whatever cache dropped
                        dropped = set(model) - set(dict(c))
                        if not dropped:
                            print("NO-EVICT", cls.__name__, max_size, dict(c)); sys.exit(1)
                        for dkey in dropped: del model[dkey]
                    if k in model and model[k] != v and dict(c).get(k) != v:
                        print("STALE", cls.__name__, dict(c)); sys.exit(1)
                    model[k] = v
                    # bound check
                    if len(c) > max_size: print("OVER-CAP", cls.__name__, len(c)); sys.exit(1)
                elif op == 'del':
                    if k in model:
                        del c[k]; del model[k]
                elif op == 'pop':
                    r = c.pop(k, None)
                    if k in model:
                        del model[k]
                elif op == 'popitem':
                    if len(c):
                        pk, pv = c.popitem()
                        if model.get(pk) != pv: print("POPITEM-V", cls.__name__, pk, pv, model); sys.exit(1)
                        del model[pk]
                elif op == 'clear':
                    c.clear(); model = {}
                if not check(c, model, "%s/%d/%d/%s" % (cls.__name__, max_size, i, op)):
                    sys.exit(1)
print("ALL CONSISTENT")
