import sys, random, copy, importlib.util

def load(name, path):
    spec = importlib.util.spec_from_file_location(name, path)
    m = importlib.util.module_from_spec(spec)
    sys.modules[name] = m
    spec.loader.exec_module(m)
    return m

pristine = load("cutils_pristine", "pristine/repo/boltons/cacheutils.py")
fixed    = load("cutils_fixed", "repo/boltons/cacheutils.py")

# NOTE: load both; each module is self-contained (no package deps? it imports boltons? check)
diffs = []
def run(cls, ops, max_size, on_miss=None):
    c = cls(max_size=max_size, on_miss=on_miss)
    log = []
    for op, k, v in ops:
        try:
            if op == 'set': c[k] = v
            elif op == 'get':
                try: r = c[k]
                except KeyError: r = 'KEYERR'
                log.append(('get', k, r))
            elif op == 'del':
                try: del c[k]
                except KeyError: pass
            elif op == 'evict-check': pass
        except Exception as e:
            log.append(('exc', type(e).__name__))
        # snapshot: ll order, dict keys+values, counters, getitem view
        ll = [(kk, vv) for kk, vv in c._get_flattened_ll()[1:]]
        log.append(('snap', ll, dict(c), (c.hit_count, c.miss_count, c.soft_miss_count),
                    {k2: c._link_lookup[k2][3] for k2 in c._link_lookup}))
    return log

random.seed(7)
for cls_name in ('LRI', 'LRU'):
    for max_size in (1,2,3):
        for t in range(300):
            ops = []
            for i in range(25):
                op = random.choice(['set','set','get','del'])
                ops.append((op, random.choice('abcd'), random.randint(0,9)))
            p = run(getattr(pristine, cls_name), ops, max_size, on_miss=lambda k: 'OM')
            f = run(getattr(fixed, cls_name), ops, max_size, on_miss=lambda k: 'OM')
            for i,(pl,fl) in enumerate(zip(p,f)):
                # compare everything EXCEPT dict snapshot values (that's the fix);
                # ll order and counters must match exactly
                if pl[0]=='snap' and fl[0]=='snap':
                    if pl[1]!=fl[1]: diffs.append(('ll-order',cls_name,max_size,i,pl[1],fl[1]))
                    if pl[3]!=fl[3]: diffs.append(('counters',cls_name,max_size,i,pl[3],fl[3]))
                    if set(pl[2])!=set(fl[2]): diffs.append(('dict-keys',cls_name,max_size,i,pl[2],fl[2]))
                    if pl[4]!=fl[4]: diffs.append(('lookup-values',cls_name,max_size,i,pl[4],fl[4]))
                    # ll values must equal fixed dict values
                    if dict(fl[1]) != fl[2]: diffs.append(('FIXED-DESYNC',cls_name,max_size,i,fl[1],fl[2]))
                elif pl!=fl:
                    diffs.append(('other',cls_name,max_size,i,pl,fl))
            # pristine ll vs pristine dict: expected to diverge (the bug); fixed must not
            for pl, fl in zip(p,f):
                if pl[0]=='snap' and dict(pl[1])!=pl[2]:
                    pass  # pristine bug, expected
                if fl[0]=='snap' and dict(fl[1])!=fl[2]:
                    diffs.append(('FIXED-BUG-REMAINING', cls_name, max_size, fl[1], fl[2]))

print("total diffs:", len(diffs))
from collections import Counter
print(Counter(d[0] for d in diffs))
for d in diffs[:8]: print(d)
