import sys
from collections import OrderedDict, UserDict

def load(path):
    for m in [k for k in sys.modules if k.startswith('boltons')]:
        del sys.modules[m]
    sys.path.insert(0, path)
    import boltons.cacheutils as cu
    sys.path.pop(0)
    return cu

def run(fn):
    try:
        return repr(fn())
    except RecursionError:
        return "RecursionError"
    except Exception as e:
        return type(e).__name__ + ":" + str(e)[:40]

class MyD(dict):
    def __eq__(self, other): return "FOREIGN"
    def __ne__(self, other): return "FOREIGN_NE"
class PlainD(dict): pass

def build(cu):
    L = {}
    L['eq_pd']        = lambda: cu.LRU(values={'color':'blue'}) == {'color':'blue'}
    L['ne_pd']        = lambda: cu.LRU(values={'color':'blue'}) != {'color':'blue'}
    L['pd_eq']        = lambda: {'color':'blue'} == cu.LRU(values={'color':'blue'})
    L['pd_ne']        = lambda: {'color':'blue'} != cu.LRU(values={'color':'blue'})
    L['empty']        = lambda: cu.LRU() == {}
    L['empty_rev']    = lambda: {} == cu.LRU()
    L['diff_len']     = lambda: cu.LRU(values={'a':1}) == {'a':1,'b':2}
    L['diff_len_rev'] = lambda: {'a':1,'b':2} == cu.LRU(values={'a':1})
    L['int']          = lambda: cu.LRU(values={'a':1}) == 5
    L['list']         = lambda: cu.LRU(values={'a':1}) == ['a',1]
    L['list_rev']     = lambda: ['a',1] == cu.LRU(values={'a':1})
    L['set']          = lambda: cu.LRU(values={'a':1}) == {'a'}
    L['od_eq']        = lambda: cu.LRU(values={'a':1}) == OrderedDict(a=1)
    L['od_ne']        = lambda: cu.LRU(values={'a':1}) != OrderedDict(a=1)
    L['od_rev']       = lambda: OrderedDict(a=1) == cu.LRU(values={'a':1})
    L['od_rev_ne']    = lambda: OrderedDict(a=1) != cu.LRU(values={'a':1})
    L['od_diff']      = lambda: cu.LRU(values={'a':1}) == OrderedDict(a=2)
    L['ud_eq']        = lambda: cu.LRU(values={'a':1}) == UserDict(a=1)
    L['ud_ne']        = lambda: cu.LRU(values={'a':1}) != UserDict(a=1)
    L['ud_rev']       = lambda: UserDict(a=1) == cu.LRU(values={'a':1})
    L['myd_eq']       = lambda: cu.LRU(values={'a':1}) == MyD(a=1)
    L['myd_rev']      = lambda: MyD(a=1) == cu.LRU(values={'a':1})
    L['plaind_eq']    = lambda: cu.LRU(values={'a':1}) == PlainD(a=1)
    L['plaind_rev']   = lambda: PlainD(a=1) == cu.LRU(values={'a':1})
    L['lri_lri']      = lambda: cu.LRI(values={'a':1}) == cu.LRI(values={'a':1})
    L['lri_lri_ne']   = lambda: cu.LRI(values={'a':1}) != cu.LRI(values={'a':2})
    L['lru_lri']      = lambda: cu.LRU(values={'a':1}) == cu.LRI(values={'a':1})
    L['self']         = lambda: (lambda c: c == c)(cu.LRU(values={'a':1}))
    L['dict_of_cache']= lambda: {'k': cu.LRU(values={'a':1})} == {'k': {'a':1}}
    L['in_list']      = lambda: cu.LRU(values={'a':1}) in [{}, {'a':1}]
    return L

results = {}
for tag, path in [('PRISTINE','work/pristine/repo'), ('FIXED','work/repo')]:
    cu = load(path)
    fns = build(cu)
    results[tag] = {name: run(fn) for name, fn in fns.items()}

keys = sorted(results['PRISTINE'])
w = max(len(k) for k in keys)
diffs = []
for k in keys:
    a, b = results['PRISTINE'][k], results['FIXED'][k]
    mark = '' if a == b else '  <== DIFF'
    if a != b: diffs.append(k)
    print(f"{k:<{w}}  pristine={a:<30} fixed={b}{mark}")
print("\nDIFFS:", diffs)
PY"}

