{"intent": "Look for residual mismatches between tilde and equivalent forms under includePrerelease", "command": "cd work/repo && node -e "
const s=require('./'); const o={includePrerelease:true}
const pairs=[['~3.4','3.4.*'],['~3','3.x'],['~1.2','1.2.x'],['~1','1.x'],['~0','0.x'],['~0.2','0.2.x']]
let mismatches=0
for(const [a,b] of pairs){
  const ra=new s.Range(a,o), rb=new s.Range(b,o)
  if(ra.range!==rb.range){console.log('RANGE DIFF',a,ra.range,b,rb.range);mismatches++}
}
console.log(mismatches?'mismatches='+mismatches:'all tilde/xrange expansions identical')
""}

