// `version`?  This mirrors the range-level prerelease gate in Range.test: a
// prerelease version is only allowed when some comparator in the range carries
// a prerelease of the very same major.minor.patch tuple.
const allowsPrerelease = (version, comps, options) => {
  if (!version.prerelease.length || options.includePrerelease) {
    return true
