{"intent": "Differential test: generator input must behave exactly like list input", "command": "cd work/repo && PYTHONPATH=. python3 - <<'EOF'
from boltons.dictutils import OrderedMultiDict as OMD
from boltons.urlutils import QueryParamDict

def snap(omd):
    return (len(omd), list(omd.keys()), list(omd.keys(multi=True)),
            list(omd.items(multi=True)), repr(omd),
            [tuple(omd.iteritems(multi=True))], list(reversed(omd)))

failures = []

def check(name, build_list, build_gen, extra=None):
    a = OMD(); b = OMD()
    try:
        build_list(a); build_gen(b)
        sa, sb = snap(a), snap(b)
        if sa != sb:
            failures.append((name, sa, sb))
        if a != b:
            failures.append((name + ' [eq]', repr(a), repr(b)))
        # internal consistency: len(keys) == len, items count == sum of getlist lens
        for o, tag in ((a, 'list'), (b, 'gen')):
            if len(list(o.keys())) != len(o):
                failures.append((name, tag, 'keys/len mismatch', list(o.keys()), len(o)))
            n_items = len(list(o.items(multi=True)))
            n_vals = sum(len(o.getlist(k)) for k in o.keys())
            if n_items != n_vals:
                failures.append((name, tag, 'items/values mismatch', n_items, n_vals))
            if n_items != len(list(o.iterkeys(multi=True))):
                failures.append((name, tag, 'iterkeys mismatch'))
        if extra: extra(a, b)
    except Exception as e:
        failures.append((name, 'EXC', type(e).__name__, str(e)))

# basic from report
check('gen3', lambda o: o.addlist('k', [0,2,4]), lambda o: o.addlist('k', (n*2 for n in range(3))))
check('empty', lambda o: o.addlist('k', []), lambda o: o.addlist('k', iter([])))
# existing key
check('append-existing', lambda o: (o.add('k', 1), o.addlist('k', [2,3])),
                    lambda o: (o.add('k', 1), o.addlist('k', (x for x in (2,3)))))
# single item
check('single', lambda o: o.addlist('k', [5]), lambda o: o.addlist('k', (x for x in [5])))
# str / tuple / range re-iterables
check('range', lambda o: o.addlist('a', range(3)), lambda o: o.addlist('a', range(3)))
# interleaved keys
check('multikey', lambda o: (o.addlist('a',[1]), o.addlist('b',[2]), o.addlist('a',[3])),
                    lambda o: (o.addlist('a',(x for x in [1])), o.addlist('b',(x for x in [2])), o.addlist('a',(x for x in [3]))))
# copy/pickle roundtrip after generator add
import pickle
def rt(a, b):
    for o, tag in ((a,'list'),(b,'gen')):
        c = o.copy()
        if snap(c) != snap(o): failures.append(('copy', tag, repr(o), repr(c)))
        try:
            p = pickle.loads(pickle.dumps(o))
            if snap(p) != snap(o): failures.append(('pickle', tag, repr(o), repr(p)))
        except Exception as e:
            failures.append(('pickle', tag, 'EXC', repr(e)))
check('rt', lambda o: o.addlist('k', [1,2]), lambda o: o.addlist('k', (x for x in [1,2])), extra=rt)

# map/setdefault/pop interactions
def popcheck(a, b):
    for o, tag in ((a,'list'),(b,'gen')):
        if o.popall('k', 'MISSING') == 'MISSING' and o: failures.append(('popall', tag, repr(o)))
check('pop', lambda o: o.addlist('k', [1,2]), lambda o: o.addlist('k', (x for x in [1,2])), extra=popcheck)

# QueryParamDict
qpa, qpb = QueryParamDict(), QueryParamDict()
qpa.addlist('q', ['a','b']); qpb.addlist('q', (c for c in 'ab'))
if snap(qpa) != snap(qpb) or qpa.to_text() != qpb.to_text():
    failures.append(('qp', repr(qpa), repr(qpb), qpa.to_text(), qpb.to_text()))

print("FAILURES:" if failures else "ALL CONSISTENT")
for f in failures: print(" ", f)
EOF"}

