from boltons.dictutils import OrderedMultiDict

# Case 1: iterable whose __bool__ raises (numpy-ndarray-style truthiness)
class AmbiguousArray:
    def __init__(self, items): self._items = items
    def __iter__(self): return iter(self._items)
    def __bool__(self): raise ValueError("truth value of an array is ambiguous")

omd = OrderedMultiDict()
try:
    omd.addlist('k', AmbiguousArray([1, 2, 3]))
    print("ambiguous: OK", omd.getlist('k'))
except Exception as e:
    print("ambiguous: FAILS ->", type(e).__name__, e)
    print("  equivalent list works:", end=" ")
    o2 = OrderedMultiDict(); o2.addlist('k', [1,2,3]); print(o2.getlist('k'))

# Case 2: one-shot iterable that is falsy but yields items when iterated
class FalsyOneShot:
    def __init__(self): self._it = iter([7, 8, 9])
    def __bool__(self): return False
    def __iter__(self): return self
    def __next__(self): return next(self._it)

omd3 = OrderedMultiDict()
omd3.addlist('k', FalsyOneShot())
print("falsy one-shot -> getlist:", omd3.getlist('k'), "len:", len(omd3),
      "| equivalent list gives [7, 8, 9]")

# Case 3: one-shot iterator with __len__ == 0 but non-empty iteration
class LenZeroOneShot:
    def __len__(self): return 0
    def __iter__(self): return iter([1, 2])

omd4 = OrderedMultiDict()
omd4.addlist('k', LenZeroOneShot())
print("len-0 one-shot -> getlist:", omd4.getlist('k'), "len:", len(omd4))
