import random, re, math
from humanize.filesize import naturalsize as ns
from humanize.filesize import suffixes

random.seed(0)
suffix_map = {'dec': suffixes['decimal'], 'bin': suffixes['binary'], 'gnu': suffixes['gnu']}
bad = []
def check(v, mode, fmt):
    binary = mode=='bin'; gnu = mode=='gnu'
    out = ns(v, binary=binary, gnu=gnu, format=fmt)
    sfx = suffix_map[mode]
    # locate suffix
    idx = None
    for i in range(len(sfx)-1, -1, -1):
        if out.endswith(sfx[i]):
            idx = i; break
    if idx is None:
        # B / Byte forms
        return
    exp = idx + 1
    base = 1024 if (gnu or binary) else 1000
    numstr = out[:len(out)-len(sfx[idx])].rstrip('' if gnu else ' ')
    # recompute what the display should be for this suffix
    expected_num = fmt % (float(v) / base**exp)
    if numstr != expected_num:
        bad.append(('mismatch', v, mode, fmt, out, expected_num))
    n = float(numstr)
    if n < 1:
        bad.append(('under1', v, mode, fmt, out))
    if n >= base and idx != len(sfx)-1:
        bad.append(('over-base', v, mode, fmt, out))

modes = ['dec','bin','gnu']
fmts = ['%.1f','%.0f','%.2f','%.3f','%d','%g','%.1e','%10.1f']
# boundary clusters + randoms
vals = set()
for base in (1000,1024):
    for e in range(1,11):
        b = base**e
        for d in (1,2,10,b//1000,int(b*4.9e-5),int(b*6e-5),b//2,b-1,b,b+1):
            vals.add(b-d); vals.add(b+d)
for _ in range(3000):
    e = random.randint(1,12)
    base = random.choice([1000,1024])
    vals.add(random.randint(base**(e-1), base**e))
vals |= {999_960, 999_980_000, 1024**3-1, 10**30-1, 1024**10-1, 10**34*3}
count=0
for v in vals:
    if v <= 0: continue
    for m in modes:
        for f in fmts:
            check(v,m,f); count+=1
print('checked', count, 'bad', len(bad))
for x in bad[:25]: print(x)
