import sys, math, re
sys.path.insert(0,'src')
import humanize

SUP = str.maketrans("⁻⁰¹²³⁴⁵⁶⁷⁸⁹", "-0123456789")

def parse(out):
    # scientific form
    m = re.fullmatch(r"(-?[\d.]+) x 10([⁻⁰¹²³⁴⁵⁶⁷⁸⁹]+)(.*)", out)
    if m:
        exp = int(m.group(2).translate(SUP))
        return ('sci', float(m.group(1)), exp, m.group(3))
    m = re.fullmatch(r"(-?[\d.]+)([a-zA-Zμ°′″]*)(.*)", out)
    if m:
        return ('man', float(m.group(1)), m.group(2), m.group(3))
    return ('BAD', out, None, None)

def round_sig(x, p):
    # round double x to p significant figures (exact binary rounding, like format())
    if x == 0: return 0.0
    k = p - 1 - math.floor(math.log10(abs(x)))
    return round(x, k)

def check(v, unit, p):
    out = humanize.metric(v, unit, p)
    kind = parse(out)
    if kind[0] == 'BAD':
        return f"parse-fail {v!r} p{p} -> {out!r}"
    r = round_sig(v, p)
    if kind[0] == 'sci':
        _, man, exp, u = kind
        val = man * 10**exp
        if u != unit: return f"unit {v!r} p{p} -> {out!r}"
        if r != 0 and abs(val - r) > abs(r)*1e-9:
            return f"sci-mismatch {v!r} p{p} -> {out!r} (ref {r!r})"
        return None
    _, man, pref, u = kind
    if u != unit: return f"unit {v!r} p{p} -> {out!r} (unit {u!r})"
    # reconstruct exponent from prefix
    POS = "kMGTPEZYRQ"; NEG = "mμnpfazyrq"
    if pref in POS: b = (POS.index(pref)+1)*3
    elif pref in NEG: b = -(NEG.index(pref)+1)*3
    elif pref == "": b = 0
    else: return f"prefix {v!r} p{p} -> {out!r}"
    val = man * 10**b
    # mantissa must be within [1, 1000) up to the trailing-zero ambiguity
    am = abs(man)
    if not (1 <= am < 1000):
        return f"range {v!r} p{p} -> {out!r} mantissa {man}"
    if r != 0 and abs(val - r) > max(abs(r),abs(val))*1e-9:
        return f"mismatch {v!r} p{p} -> {out!r} (ref {r!r})"
    # digit count: mantissa string digits (minus '.') should be <= p unless
    # rounding to p sig figs naturally yields that many trailing zeros
    digits = re.sub(r'[.\-]', '', out.split(' ')[0].split(unit)[0] if unit else out.split(' ')[0])
    digits = digits.rstrip('0') if set(digits) - {'0'} else digits
    return None

problems = []
mants = [1.0, 1.00001, 5.0, 9.995, 9.995001, 9.9996, 9.99999, 10.0001, 99.95, 99.996,
         99.9999, 100.001, 999.5, 999.96, 999.999, 0.99996, 0.0999996, 555.5]
exps = list(range(-36, 39))
for p in range(1, 7):
    for e in exps:
        for m in mants:
            for v in (m * 10.0**e, -m * 10.0**e):
                if not math.isfinite(v) or v == 0: continue
                prob = check(v, "", p)
                if prob: problems.append(prob)
# also a few int-ish values and unit cases
for p in (1,2,3,4,5):
    for v in (9996, 99960, 999600, 9996000, 10400, 104000, 1040000,
              999999999999999999999999999999999, 9999999999999999999999999999999999,
              10**33, 10**32, 10**-33, 10**-30,
              99999999999999999999999999999999.9):
        prob = check(v, "W", p)
        if prob: problems.append(prob)

print(len(problems), "problems")
for x in problems[:40]: print(" ", x)
EOF"}

