            try:
                v = s.pop(i); ok = True
            except IndexError:
                v, ok = None, False
            if -len(model) <= i < len(model):
                if not ok or v != model[i] or list(s) != model[:i] + model[i+1:]:
                    bad.append((trial, step, 'popidx', i, v, list(s), model))
            else:
