from math import log
from humanize.filesize import naturalsize
from humanize.filesize import suffixes

def ref(value, binary=False, gnu=False, format="%.1f"):
    # expected: same as passing the "round value" (value rounded to nearest unit boundary step)
    # i.e. compute scaled at floor unit, round via format, if >= base move up
    suffix = suffixes["gnu"] if gnu else (suffixes["binary"] if binary else suffixes["decimal"])
    base = 1024 if (gnu or binary) else 1000
    b = float(value)
    ab = abs(b)
    if ab == 1 and not gnu:
        return "%d Byte" % int(b)
    if ab < base:
        return ("%dB" if gnu else "%d Bytes") % int(b)
    exp = int(min(log(ab, base), len(suffix)))
    scaled = b / (base**exp)
    try:
        up = abs(float(format % scaled)) >= base
    except ValueError:
        up = None  # unknown
    if up and exp < len(suffix):
        exp += 1
        scaled = b / (base**exp)
    space = "" if gnu else " "
    return format % scaled + space + suffix[exp-1]

# sanity: run the reported cases
print("reported:", naturalsize(999_960), naturalsize(999_980_000), naturalsize(1024**3-1, binary=True))

# fuzz: near unit boundaries, all modes, several formats
bad = []
bases = [(1000, False, False), (1024, False, True), (1024, True, False)]
formats = ["%.1f", "%.2f", "%.0f", "%.3f", "%d", "%.4f", "%e", "%.1f%%", "%,.1f"]
for base, binary, gnu in bases:
    suffix_len = 10
    for e in range(1, suffix_len+1):
        for mult in [0.99994, 0.99999, 0.9999999, 1.0, 1.000001, 1.00006]:
            v = int(base**e * mult) if base**e * mult < 1e300 else base**e * mult
            if v < base: continue
            for fmt in formats:
                try:
                    got = naturalsize(v, binary=binary, gnu=gnu, format=fmt)
                except Exception as ex:
                    got = f"RAISED {type(ex).__name__}: {ex}"
                try:
                    expd = ref(v, binary=binary, gnu=gnu, format=fmt)
                except Exception as ex:
                    expd = f"RAISED {type(ex).__name__}: {ex}"
                if got != expd:
                    bad.append((v, binary, gnu, fmt, got, expd))

# also negatives
for base, binary, gnu in bases:
    for e in range(1, 11):
        v = -int(base**e * 0.99996)
        if abs(v) < base: continue
        for fmt in ["%.1f", "%.0f", "%.3f"]:
            try:
                got = naturalsize(v, binary=binary, gnu=gnu, format=fmt)
            except Exception as ex:
                got = f"RAISED {type(ex).__name__}: {ex}"
            try:
                expd = ref(v, binary=binary, gnu=gnu, format=fmt)
            except Exception as ex:
                expd = f"RAISED {type(ex).__name__}: {ex}"
            if got != expd:
                bad.append((v, binary, gnu, fmt, got, expd))

print("mismatches:", len(bad))
for row in bad[:40]:
